using GeminiGatewayClient.Serialization;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace GeminiGatewayClient.Models;

/// <summary>
/// Code generated by the model that is meant to be executed, where the result is returned to the model.
/// </summary>
public sealed class ExecutableCode
{
    /// <summary>
    /// Gets or sets the programming language of the <see cref="Code"/>.
    /// </summary>
    [JsonPropertyName("language")]
    public CodeExecutionLanguage? Language { get; set; }

    /// <summary>
    /// Gets or sets the code to be executed.
    /// </summary>
    [JsonPropertyName("code")]
    public string? Code { get; set; }

    /// <summary>
    /// Gets or sets additional JSON properties not explicitly modeled by this type.
    /// </summary>
    [JsonExtensionData]
    public IDictionary<string, JsonElement>? ExtensionData { get; set; }
}

/// <summary>
/// Result of executing the <see cref="ExecutableCode"/>.
/// </summary>
public sealed class CodeExecutionResult
{
    /// <summary>
    /// Gets or sets the outcome of the code execution.
    /// </summary>
    [JsonPropertyName("outcome")]
    public CodeExecutionOutcome? Outcome { get; set; }

    /// <summary>
    /// Gets or sets stdout when code execution succeeds, or stderr / diagnostic description when it fails.
    /// </summary>
    [JsonPropertyName("output")]
    public string? Output { get; set; }

    /// <summary>
    /// Gets or sets additional JSON properties not explicitly modeled by this type.
    /// </summary>
    [JsonExtensionData]
    public IDictionary<string, JsonElement>? ExtensionData { get; set; }
}

/// <summary>
/// Supported programming languages for generated executable code.
/// </summary>
[JsonConverter(typeof(LenientStringEnumConverter<CodeExecutionLanguage>))]
public enum CodeExecutionLanguage
{
    /// <summary>Unspecified language.</summary>
    [JsonStringEnumMemberName("LANGUAGE_UNSPECIFIED")]
    Unspecified = 0,

    /// <summary>Python (&gt;= 3.10) with standard scientific libraries.</summary>
    [JsonStringEnumMemberName("PYTHON")]
    Python = 1,

    /// <summary>Fallback value used when the server returns an unrecognized language.</summary>
    Unknown = -1,
}

/// <summary>
/// Enumeration of possible outcomes of a code execution.
/// </summary>
[JsonConverter(typeof(LenientStringEnumConverter<CodeExecutionOutcome>))]
public enum CodeExecutionOutcome
{
    /// <summary>Unspecified status.</summary>
    [JsonStringEnumMemberName("OUTCOME_UNSPECIFIED")]
    Unspecified = 0,

    /// <summary>Code execution completed successfully.</summary>
    [JsonStringEnumMemberName("OUTCOME_OK")]
    Ok = 1,

    /// <summary>Code execution finished but with a failure (stderr should contain the reason).</summary>
    [JsonStringEnumMemberName("OUTCOME_FAILED")]
    Failed = 2,

    /// <summary>Code execution ran for too long and was cancelled.</summary>
    [JsonStringEnumMemberName("OUTCOME_DEADLINE_EXCEEDED")]
    DeadlineExceeded = 3,

    /// <summary>Fallback value used when the server returns an unrecognized outcome.</summary>
    Unknown = -1,
}

